# Find the bs_brand_bundle definition location and peek more of it
loc <- regexpr("bs_brand_bundle <- function\\(brand, version = version_default\\(\\)\\)", .context$bslib_source)
loc
if (loc > 0) {
  start <- max(1, loc - 400)
  end <- min(nchar(.context$bslib_source), loc + 1200)
  cat(peek(.context$bslib_source, start, end))
} else {
  cat('bs_brand_bundle definition not found via regexpr\n')
}

# Locate bs_brand_bundle definition using fixed string search
loc <- regexpr("bs_brand_bundle <- function", .context$bslib_source, fixed = TRUE)
loc
if (loc > 0) {
  start <- max(1, loc - 400)
  end <- min(nchar(.context$bslib_source), loc + 4000)
  cat(peek(.context$bslib_source, start, end))
} else {
  cat('bs_brand_bundle not found')
}

# Search for occurrences of 'brand_color' and 'brand_defaults'
bc <- search(.context$bslib_source, "brand_color")
bd <- search(.context$bslib_source, "brand_defaults")
cat('\nOccurrences of brand_color:', length(bc), 'and brand_defaults:', length(bd), '\n')
head(bc, 40)
head(bd, 40)

# Peek around each occurrence of 'brand_color' (up to first 10)
for (i in seq_len(min(10, length(bc)))) {
  idx <- regexpr(bc[i], .context$bslib_source, fixed = TRUE)
  if (idx > 0) {
    s <- max(1, idx - 200)
    e <- min(nchar(.context$bslib_source), idx + nchar(bc[i]) + 200)
    cat(sprintf('\n--- brand_color occurrence %d at pos %d ---\n', i, idx))
    cat(peek(.context$bslib_source, s, e))
  }
}

# Search for 'foreground' occurrences and show contexts for first 20
fg <- search(.context$bslib_source, "foreground")
cat('\nTotal foreground matches:', length(fg), '\n')
for (i in seq_len(min(20, length(fg)))) {
  idx <- regexpr(fg[i], .context$bslib_source, fixed = TRUE)
  s <- max(1, idx - 160)
  e <- min(nchar(.context$bslib_source), idx + nchar(fg[i]) + 160)
  cat(sprintf('\n--- foreground occurrence %d at pos %d ---\n', i, idx))
  cat(peek(.context$bslib_source, s, e))
}

# Also search for functions that might convert or set colors into SASS variables
candidates <- c("sass_vars", "sass_variable", "bs_add_variables", "sass::", "sass_variables", "bs_add_sass")
for (pat in candidates) {
  res <- search(.context$bslib_source, pat)
  if (length(res) > 0) {
    cat(sprintf('\nMatches for pattern "%s": %d\n', pat, length(res)))
    print(head(res, 10))
  }
}

# Search for the '_brand-yml.scss' file content in the bslib source
matches_scss <- search(.context$bslib_source, "_brand-yml.scss")
length(matches_scss)
print(head(matches_scss, 30))

# If found, peek around the first occurrence to display the SASS content
if (length(matches_scss) > 0) {
  idx <- regexpr(matches_scss[1], .context$bslib_source, fixed = TRUE)
  # find start of the FILE block that contains this path (look for '# ---- FILE:' preceding it)
  # Find the nearest '# ---- FILE:' before idx
  file_markers <- gregexpr("# ---- FILE:", .context$bslib_source, fixed = TRUE)[[1]]
  file_pos <- tail(file_markers[file_markers < idx], 1)
  if (length(file_pos) && file_pos > 0) {
